class ToolCall(BaseModel):
    name: str
    args: dict[str, Any]
    fingerprint: str = ""
    id: str = ""

    def __init__(self, /, **data):
        super().__init__(**data)
        canonical = {"name": self.name, "args": _canonicalize(self.args)}
        digest = hashlib.sha256(
            json.dumps(canonical, sort_keys=True, separators=(",", ":")).encode("utf-8")
        ).hexdigest()
        object.__setattr__(self, "fingerprint", digest)
        object.__setattr__(self, "id", digest[:8])

def _canonicalize(value: Any) -> Any:
    """Recursively canonicalize a value for stable fingerprinting.

    Sorts dict keys, converts tuples to lists, and strips leading/trailing
    whitespace from strings. Numeric and boolean types are left untouched.
    """
    if isinstance(value, dict):
        return {k: _canonicalize(v) for k, v in sorted(value.items())}
    if isinstance(value, tuple):
        return [_canonicalize(item) for item in value]
    if isinstance(value, list):
        return [_canonicalize(item) for item in value]
    if isinstance(value, str):
        return value.strip()
    return value


